"use server";

import { revalidatePath } from "next/cache";
import { addBook, markFinished, ValidationError } from "@/lib/books";

export type AddBookState = { error: string | null; ok: boolean };

export async function addBookAction(
  _prev: AddBookState,
  formData: FormData,
): Promise<AddBookState> {
  try {
    await addBook({
      title: formData.get("title") as string,
      author: formData.get("author") as string,
      notes: formData.get("notes") as string,
    });
  } catch (err) {
    if (err instanceof ValidationError) return { error: err.message, ok: false };
    throw err;
  }
  revalidatePath("/");
  return { error: null, ok: true };
}

export async function markFinishedAction(formData: FormData): Promise<void> {
  const id = formData.get("id");
  if (typeof id !== "string") return;
  await markFinished(id);
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
}

