"use client";

import { useActionState, useEffect, useRef } from "react";
import { addBookAction, type AddBookState } from "./actions";
import { LIMITS } from "@/lib/limits";

const initialState: AddBookState = { error: null, ok: false };

export function AddBookForm() {
  const [state, formAction, pending] = useActionState(addBookAction, initialState);
  const formRef = useRef<HTMLFormElement>(null);

  useEffect(() => {
    if (state.ok) formRef.current?.reset();
  }, [state]);

  return (
    <form ref={formRef} action={formAction} className="add-form">
      <label>
        Title
        <input name="title" required maxLength={LIMITS.title} />
      </label>
      <label>
        Author
        <input name="author" required maxLength={LIMITS.author} />
      </label>
      <label>
        Notes
        <textarea name="notes" rows={3} maxLength={LIMITS.notes} />
      </label>
      {state.error && <p className="error">{state.error}</p>}
      <button type="submit" disabled={pending}>
        {pending ? "Adding…" : "Add book"}
      </button>
    </form>
  );
}

