import Link from "next/link";
import { listBooks, type Book } from "@/lib/books";
import { markFinishedAction } from "./actions";
import { AddBookForm } from "./add-book-form";

// The book list lives in a file that changes at runtime, so never prerender.
export const dynamic = "force-dynamic";

export default async function Home() {
  const books = await listBooks();
  const reading = books.filter((b) => b.status === "reading");
  const finished = books
    .filter((b) => b.status === "finished")
    .sort((a, b) => (b.finishedAt ?? "").localeCompare(a.finishedAt ?? ""));

  return (
    <>
      <section>
        <h2>Currently reading</h2>
        {reading.length === 0 ? (
          <p className="empty">Nothing on the go. Add a book below.</p>
        ) : (
          <ul className="books">
            {reading.map((book) => (
              <li key={book.id}>
                <BookLink book={book} />
                <form action={markFinishedAction}>
                  <input type="hidden" name="id" value={book.id} />
                  <button type="submit">Mark finished</button>
                </form>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2>Finished</h2>
        {finished.length === 0 ? (
          <p className="empty">No finished books yet.</p>
        ) : (
          <ul className="books">
            {finished.map((book) => (
              <li key={book.id}>
                <BookLink book={book} />
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2>Add a book</h2>
        <AddBookForm />
      </section>
    </>
  );
}

function BookLink({ book }: { book: Book }) {
  return (
    <Link href={`/books/${book.id}`}>
      <strong>{book.title}</strong> <span className="author">by {book.author}</span>
    </Link>
  );
}

