import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { addBook, getBook, listBooks, markFinished, ValidationError } from "./books";

let dir: string;
let file: string;

beforeEach(async () => {
  dir = await mkdtemp(path.join(tmpdir(), "books-"));
  file = path.join(dir, "nested", "books.json");
  process.env.BOOKS_FILE = file;
});

afterEach(async () => {
  delete process.env.BOOKS_FILE;
  await rm(dir, { recursive: true, force: true });
});

describe("books store", () => {
  it("starts empty when the file doesn't exist yet", async () => {
    expect(await listBooks()).toEqual([]);
  });

  it("adds a book as currently reading and persists it to disk", async () => {
    const book = await addBook({ title: "  Dune ", author: "Frank Herbert", notes: "Spice" });
    expect(book).toMatchObject({
      title: "Dune",
      author: "Frank Herbert",
      notes: "Spice",
      status: "reading",
      finishedAt: null,
    });

    const onDisk = JSON.parse(await readFile(file, "utf8"));
    expect(onDisk).toEqual([book]);
    expect(await getBook(book.id)).toEqual(book);
  });

  it("marks a book as finished", async () => {
    const book = await addBook({ title: "Emma", author: "Jane Austen" });
    const finished = await markFinished(book.id);
    expect(finished?.status).toBe("finished");
    expect(finished?.finishedAt).toEqual(expect.any(String));
    expect((await getBook(book.id))?.status).toBe("finished");
  });

  it("returns undefined for unknown ids", async () => {
    expect(await getBook("nope")).toBeUndefined();
    expect(await markFinished("nope")).toBeUndefined();
  });

  it("rejects missing or overlong fields", async () => {
    await expect(addBook({ title: " ", author: "A" })).rejects.toBeInstanceOf(ValidationError);
    await expect(addBook({ title: "T", author: "" })).rejects.toBeInstanceOf(ValidationError);
    await expect(addBook({ title: "x".repeat(201), author: "A" })).rejects.toBeInstanceOf(
      ValidationError,
    );
    expect(await listBooks()).toEqual([]);
  });

  it("doesn't lose books when adds happen concurrently", async () => {
    await Promise.all(
      Array.from({ length: 20 }, (_, i) => addBook({ title: `Book ${i}`, author: "A" })),
    );
    expect(await listBooks()).toHaveLength(20);
  });

  it("refuses to overwrite a file it can't parse", async () => {
    await addBook({ title: "Emma", author: "Jane Austen" });
    await writeFile(file, "{ not json");
    await expect(addBook({ title: "Dune", author: "Frank Herbert" })).rejects.toThrow();
    expect(await readFile(file, "utf8")).toBe("{ not json");
  });
});

