import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";
import { LIMITS } from "./limits";

export type BookStatus = "reading" | "finished";

export type Book = {
  id: string;
  title: string;
  author: string;
  notes: string;
  status: BookStatus;
  addedAt: string;
  finishedAt: string | null;
};

export type NewBook = {
  title: string;
  author: string;
  notes?: string;
};

export class ValidationError extends Error {}

function dataFile(): string {
  return process.env.BOOKS_FILE ?? path.join(process.cwd(), "data", "books.json");
}

async function readAll(): Promise<Book[]> {
  let raw: string;
  try {
    raw = await readFile(dataFile(), "utf8");
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw err;
  }
  // A file we can't parse is an error, not an empty list: treating it as empty
  // would let the next write overwrite whatever the user had saved.
  const parsed: unknown = JSON.parse(raw);
  if (!Array.isArray(parsed)) {
    throw new Error(`${dataFile()} does not contain a list of books`);
  }
  return parsed as Book[];
}

async function writeAll(books: Book[]): Promise<void> {
  const file = dataFile();
  await mkdir(path.dirname(file), { recursive: true });
  // Write to a temp file and rename so a crash mid-write can't leave a
  // truncated books.json behind.
  const tmp = `${file}.${process.pid}.${Date.now()}.tmp`;
  await writeFile(tmp, JSON.stringify(books, null, 2) + "\n", "utf8");
  await rename(tmp, file);
}

// Serialize read-modify-write cycles so two requests arriving together can't
// each read the old list and have one overwrite the other's change.
let queue: Promise<unknown> = Promise.resolve();

function update<T>(fn: (books: Book[]) => { books: Book[]; result: T }): Promise<T> {
  const run = queue.then(async () => {
    const { books, result } = fn(await readAll());
    await writeAll(books);
    return result;
  });
  queue = run.catch(() => {});
  return run;
}

export async function listBooks(): Promise<Book[]> {
  await queue;
  return readAll();
}

export async function getBook(id: string): Promise<Book | undefined> {
  return (await listBooks()).find((b) => b.id === id);
}

function clean(value: unknown, field: keyof typeof LIMITS, required: boolean): string {
  const text = typeof value === "string" ? value.trim() : "";
  if (required && !text) throw new ValidationError(`Please enter a ${field}.`);
  if (text.length > LIMITS[field]) {
    throw new ValidationError(`The ${field} can be at most ${LIMITS[field]} characters.`);
  }
  return text;
}

export function addBook(input: NewBook): Promise<Book> {
  const book: Book = {
    id: randomUUID(),
    title: clean(input.title, "title", true),
    author: clean(input.author, "author", true),
    notes: clean(input.notes, "notes", false),
    status: "reading",
    addedAt: new Date().toISOString(),
    finishedAt: null,
  };
  return update((books) => ({ books: [...books, book], result: book }));
}

export function markFinished(id: string): Promise<Book | undefined> {
  return update((books) => {
    const book = books.find((b) => b.id === id);
    if (book && book.status !== "finished") {
      book.status = "finished";
      book.finishedAt = new Date().toISOString();
    }
    return { books, result: book };
  });
}

