export async function getBook(id: string): Promise<Book | undefined> {
  return (await listBooks()).find((b) => b.id === id);
}

function clean(value: unknown, field: keyof typeof LIMITS, required: boolean): string {
  const text = typeof value === "string" ? value.trim() : "";
  if (required && !text) throw new ValidationError(`Please enter a ${field}.`);
  if (text.length > LIMITS[field]) {
    throw new ValidationError(`The ${field} can be at most ${LIMITS[field]} characters.`);
  }
  return text;
}

export async function addBook(input: NewBook): Promise<Book> {
  const book: Book = {
    id: randomUUID(),
    title: clean(input.title, "title", true),
    author: clean(input.author, "author", true),
    notes: clean(input.notes, "notes", false),
    status: "reading",
    addedAt: new Date().toISOString(),
    finishedAt: null,
  };
  return update((books) => ({ books: [...books, book], result: book }));
}

export function markFinished(id: string): Promise<Book | undefined> {
  return update((books) => {
    const book = books.find((b) => b.id === id);
    if (book && book.status !== "finished") {
      book.status = "finished";
      book.finishedAt = new Date().toISOString();
    }
    return { books, result: book };
  });
}
